-- Explicit rollback only while every persisted tenant snapshot is still free v1.
BEGIN;
SET LOCAL ROLE celebix_saas_owner;
SET LOCAL search_path=pg_catalog,saas;
SET LOCAL lock_timeout='5s';
SET LOCAL statement_timeout='120s';
LOCK TABLE saas.tenant_operations IN ACCESS EXCLUSIVE MODE;
DO $guard$ BEGIN
 IF current_setting('celebix.allow_starter255_down',true) IS DISTINCT FROM 'on' THEN RAISE EXCEPTION 'STARTER255_DOWN_REQUIRES_EXPLICIT_OPERATOR';END IF;
 IF EXISTS(SELECT 1 FROM saas.tenant_operations WHERE result_payload IS NOT NULL AND result_payload#>>'{plan,version}' IS DISTINCT FROM '1') THEN RAISE EXCEPTION 'STARTER255_DOWN_NON_V1_SNAPSHOTS';END IF;
END $guard$;
DO $patch$
DECLARE before pg_constraint%ROWTYPE;after pg_constraint%ROWTYPE;definition text;needle text;replacement text;protected_constraints jsonb;protected_triggers jsonb;table_authority jsonb;
BEGIN
 SELECT * INTO STRICT before FROM pg_constraint WHERE conrelid='saas.tenant_operations'::regclass AND conname='tenant_operations_result_payload_shape_check';
 IF encode(sha256(convert_to(pg_get_constraintdef(before.oid),'UTF8')),'hex')<>'b3fc157237969ac0db8bf44adbaf8ca216f71b224c764d8db9bd97dfc7fec775'
  OR before.contype<>'c' OR NOT before.convalidated OR before.condeferrable OR before.condeferred OR NOT before.conislocal OR before.coninhcount<>0 OR before.connoinherit
  OR (SELECT relowner FROM pg_class WHERE oid=before.conrelid)<>'celebix_saas_owner'::regrole
 THEN RAISE EXCEPTION 'STARTER255_PREDECESSOR_DRIFT';END IF;
 SELECT to_jsonb(c)-ARRAY['relpages','reltuples','relallvisible','relfrozenxid','relminmxid'] INTO table_authority FROM pg_class c WHERE oid=before.conrelid;
 SELECT jsonb_agg(to_jsonb(c) ORDER BY c.oid) INTO protected_constraints FROM pg_constraint c WHERE c.conrelid=before.conrelid AND c.oid<>before.oid;
 SELECT jsonb_agg(to_jsonb(t) ORDER BY t.oid) INTO protected_triggers FROM pg_trigger t WHERE t.tgrelid=before.conrelid;
 definition:=pg_get_constraintdef(before.oid);
 definition:=$predecessor$CHECK (((result_payload IS NULL) OR (((jsonb_typeof(result_payload) = 'object'::text) AND ((result_payload - ARRAY['schemaVersion'::text, 'operationId'::text, 'replayed'::text, 'store'::text, 'primaryDomain'::text, 'membership'::text, 'plan'::text, 'mediaStorage'::text, 'provisioningStatus'::text, 'panelUrl'::text, 'storefrontUrl'::text]) = '{}'::jsonb) AND (result_payload @> '{"replayed": false, "schemaVersion": 1, "provisioningStatus": "ready"}'::jsonb) AND (result_payload ?& ARRAY['schemaVersion'::text, 'operationId'::text, 'replayed'::text, 'store'::text, 'primaryDomain'::text, 'membership'::text, 'plan'::text, 'mediaStorage'::text, 'provisioningStatus'::text, 'panelUrl'::text, 'storefrontUrl'::text]) AND (((result_payload ->> 'operationId'::text))::uuid = id) AND (jsonb_typeof((result_payload -> 'store'::text)) = 'object'::text) AND (((result_payload -> 'store'::text) - ARRAY['id'::text, 'slug'::text, 'status'::text]) = '{}'::jsonb) AND ((result_payload #>> '{store,status}'::text[]) = 'active'::text) AND (jsonb_typeof((result_payload -> 'primaryDomain'::text)) = 'object'::text) AND (((result_payload -> 'primaryDomain'::text) - ARRAY['schemaVersion'::text, 'hostname'::text, 'domainId'::text, 'domainType'::text, 'storeId'::text, 'storeSlug'::text, 'canonicalHostname'::text, 'status'::text, 'cacheVersion'::text]) = '{}'::jsonb) AND (((result_payload #>> '{primaryDomain,schemaVersion}'::text[]))::integer = 1) AND (jsonb_typeof((result_payload -> 'membership'::text)) = 'object'::text) AND (((result_payload -> 'membership'::text) - ARRAY['schemaVersion'::text, 'id'::text, 'principalId'::text, 'storeId'::text, 'role'::text, 'status'::text, 'createdAt'::text, 'updatedAt'::text]) = '{}'::jsonb) AND (((result_payload #>> '{membership,schemaVersion}'::text[]))::integer = 1) AND (jsonb_typeof((result_payload -> 'plan'::text)) = 'object'::text) AND (((result_payload -> 'plan'::text) - ARRAY['schemaVersion'::text, 'planId'::text, 'planCode'::text, 'version'::text, 'status'::text, 'features'::text, 'limits'::text, 'validFrom'::text, 'validUntil'::text]) = '{}'::jsonb) AND (((result_payload #>> '{plan,schemaVersion}'::text[]))::integer = 1) AND (jsonb_typeof((result_payload -> 'mediaStorage'::text)) = 'object'::text) AND (((result_payload -> 'mediaStorage'::text) - ARRAY['schemaVersion'::text, 'status'::text, 'version'::text]) = '{}'::jsonb) AND ((result_payload #> '{mediaStorage}'::text[]) @> '{"status": "ready", "schemaVersion": 1}'::jsonb) AND (jsonb_typeof((result_payload #> '{mediaStorage,version}'::text[])) = 'number'::text) AND (((result_payload #>> '{mediaStorage,version}'::text[]))::bigint > 0) AND (((result_payload #>> '{mediaStorage,version}'::text[]))::numeric = (((result_payload #>> '{mediaStorage,version}'::text[]))::bigint)::numeric) AND (((result_payload #>> '{store,id}'::text[]))::uuid = result_store_id) AND ((result_payload #>> '{store,slug}'::text[]) ~ '^[a-z0-9]+(-[a-z0-9]+)*$'::text) AND (((result_payload #>> '{primaryDomain,domainId}'::text[]))::uuid = result_domain_id) AND (((result_payload #>> '{primaryDomain,storeId}'::text[]))::uuid = result_store_id) AND ((result_payload #>> '{primaryDomain,storeSlug}'::text[]) = (result_payload #>> '{store,slug}'::text[])) AND ((result_payload #>> '{primaryDomain,domainType}'::text[]) = ANY (ARRAY['platform_subdomain'::text, 'custom'::text])) AND ((result_payload #>> '{primaryDomain,status}'::text[]) = 'active'::text) AND (((result_payload #>> '{primaryDomain,cacheVersion}'::text[]))::bigint > 0) AND ((result_payload #>> '{primaryDomain,hostname}'::text[]) ~ '^([a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?$'::text) AND ((result_payload #>> '{primaryDomain,canonicalHostname}'::text[]) ~ '^([a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?$'::text) AND (((result_payload #>> '{membership,id}'::text[]))::uuid = result_membership_id) AND (((result_payload #>> '{membership,principalId}'::text[]))::uuid = result_principal_id) AND (((result_payload #>> '{membership,storeId}'::text[]))::uuid = result_store_id) AND ((result_payload #>> '{membership,role}'::text[]) = 'store_owner'::text) AND ((result_payload #>> '{membership,status}'::text[]) = 'active'::text) AND ((result_payload #>> '{membership,createdAt}'::text[]) ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}\.[0-9]{3}Z$'::text) AND ((result_payload #>> '{membership,updatedAt}'::text[]) ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}\.[0-9]{3}Z$'::text) AND (((result_payload #>> '{plan,planId}'::text[]))::uuid = result_plan_id) AND ((result_payload #>> '{plan,planCode}'::text[]) = 'free_starter'::text) AND (((result_payload #>> '{plan,version}'::text[]))::integer = 1) AND ((result_payload #>> '{plan,status}'::text[]) = 'active'::text) AND ((result_payload #> '{plan,features}'::text[]) = '["catalog", "orders", "customers", "content", "media", "analytics", "checkout"]'::jsonb) AND ((result_payload #> '{plan,limits}'::text[]) = '{"staff": 1, "products": 100, "storageBytes": 1000000000, "customDomains": 0, "monthlyOrders": 100}'::jsonb) AND ((result_payload #>> '{plan,validFrom}'::text[]) ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}\.[0-9]{3}Z$'::text) AND ((NOT ((result_payload -> 'plan'::text) ? 'validUntil'::text)) OR (((result_payload #>> '{plan,validUntil}'::text[]) ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}\.[0-9]{3}Z$'::text) AND ((result_payload #>> '{plan,validUntil}'::text[]) >= (result_payload #>> '{plan,validFrom}'::text[])))) AND (jsonb_typeof((result_payload -> 'panelUrl'::text)) = 'string'::text) AND ((char_length((result_payload ->> 'panelUrl'::text)) >= 1) AND (char_length((result_payload ->> 'panelUrl'::text)) <= 2048)) AND ((result_payload ->> 'panelUrl'::text) ~ '^https://'::text) AND (jsonb_typeof((result_payload -> 'storefrontUrl'::text)) = 'string'::text) AND ((char_length((result_payload ->> 'storefrontUrl'::text)) >= 1) AND (char_length((result_payload ->> 'storefrontUrl'::text)) <= 2048)) AND ((result_payload ->> 'storefrontUrl'::text) ~ '^https://'::text)) IS TRUE)))$predecessor$;
 ALTER TABLE saas.tenant_operations DROP CONSTRAINT tenant_operations_result_payload_shape_check;
 EXECUTE 'ALTER TABLE saas.tenant_operations ADD CONSTRAINT tenant_operations_result_payload_shape_check '||definition;
 SELECT * INTO STRICT after FROM pg_constraint WHERE conrelid=before.conrelid AND conname=before.conname;
 IF (to_jsonb(before)-ARRAY['oid','conbin']) IS DISTINCT FROM (to_jsonb(after)-ARRAY['oid','conbin']) THEN RAISE EXCEPTION 'STARTER255_CONSTRAINT_AUTHORITY_CHANGED';END IF;
 IF encode(sha256(convert_to(pg_get_constraintdef(after.oid),'UTF8')),'hex')<>'de5287936475a21b01cc478e52162380d6c4799c0d9ecb0fa3faad2c726740eb' THEN RAISE EXCEPTION 'STARTER255_POSTCONDITION_DRIFT';END IF;
 IF protected_constraints IS DISTINCT FROM(SELECT jsonb_agg(to_jsonb(c) ORDER BY c.oid) FROM pg_constraint c WHERE c.conrelid=before.conrelid AND c.oid<>after.oid)
  OR protected_triggers IS DISTINCT FROM(SELECT jsonb_agg(to_jsonb(t) ORDER BY t.oid) FROM pg_trigger t WHERE t.tgrelid=before.conrelid)
  OR table_authority IS DISTINCT FROM(SELECT to_jsonb(c)-ARRAY['relpages','reltuples','relallvisible','relfrozenxid','relminmxid'] FROM pg_class c WHERE c.oid=before.conrelid)
 THEN RAISE EXCEPTION 'STARTER255_PROTECTED_AUTHORITY_CHANGED';END IF;
 IF EXISTS(SELECT 1 FROM pg_stat_xact_user_tables WHERE schemaname='saas' AND(n_tup_ins<>0 OR n_tup_upd<>0 OR n_tup_del<>0)) THEN RAISE EXCEPTION 'STARTER255_DATA_WRITE_DETECTED';END IF;
END $patch$;
COMMIT;
